// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/catalog", wrapper.GetCatalog)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/local/models/{slug}", wrapper.DeleteLocalModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/local/models/{slug}", wrapper.GetLocalModel)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/local/models/{slug}", wrapper.PutLocalModel)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/local/models/{slug}/presets/{name}", wrapper.DeleteLocalPreset)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/local/models/{slug}/presets/{name}", wrapper.GetLocalPreset)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/local/models/{slug}/presets/{name}", wrapper.PutLocalPreset)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/local/node-types/{id}", wrapper.DeleteLocalNodeType)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/local/node-types/{id}", wrapper.GetLocalNodeType)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/local/node-types/{id}", wrapper.PutLocalNodeType)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/local/prices", wrapper.DeleteLocalPrices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/local/prices", wrapper.ListLocalPrices)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/local/prices", wrapper.PutLocalPrices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/imports", wrapper.ListImports)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/imports", wrapper.StartImport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/imports/{id}", wrapper.GetImport)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/generator-runs", wrapper.StartGeneratorRun)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/generator-runs/{id}", wrapper.GetGeneratorRun)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/releases", wrapper.ListReleases)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/releases", wrapper.CreateRelease)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/releases/{version}/publish", wrapper.PublishRelease)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/cost-estimates", wrapper.ListCostEstimates)

	return m
}
